  selector: 'app-hijo',
  templateUrl: './hijo.component.html',
  styleUrls: ['./hijo.component.css']
})
export class HijoComponent implements OnChanges{

  @Input() compras : MisCompras[] =[];
  @Output() mandarMensaje

  ngOnChanges(changes: SimpleChanges): void {

  }

}
